/**
 *
 * InputNumberGroup is a wrapper for grouping increment/decrement buttons within an InputNumber compound.
 *
 * [Live Demo](https://www.primereact.org/inputnumber/)
 *
 * @module InputNumberGroup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { InputNumberRootInstance } from './InputNumberRoot.types';
/**
 * Defines passthrough(pt) options type in InputNumberGroup component.
 */
export type InputNumberGroupPassThroughType<E> = PassThroughType<InputNumberGroupInstance, E>;
/**
 * Defines passthrough(pt) options of InputNumberGroup component.
 */
export interface InputNumberGroupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: InputNumberGroupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in InputNumberGroup component.
 */
export interface InputNumberGroupProps extends BaseComponentProps<InputNumberGroupInstance, unknown, InputNumberGroupPassThrough> {
}
/**
 * Defines valid state in InputNumberGroup component.
 */
export interface InputNumberGroupState {
}
/**
 * Defines the methods and properties exposed by InputNumberGroup component.
 */
export interface InputNumberGroupExposes {
    /**
     * Instance of the InputNumber root component.
     */
    inputnumber: InputNumberRootInstance | undefined | null;
}
/**
 * Instance of InputNumberGroup component.
 */
export type InputNumberGroupInstance = ComponentInstance<InputNumberGroupProps, InputNumberGroupState, InputNumberGroupExposes>;
